 function changeGroupPreview(enabled, {onSaved, onUncertain, onError} = {}) {
  const run = () => action(async () => {
   try {
    await accountRequest('/api/community/group-preview', {
     method: 'POST', data: {enabled}, csrf: auth?.csrf, signal: AbortSignal.timeout(15000)
    });
   } catch (error) {
    if (['OFFLINE','REQUEST_TIMEOUT'].includes(error.code) || error.status >= 500) onUncertain?.();
    throw error;
   }
   onSaved?.();
   await Promise.all([loadMe(), loadRoom()]);
   return true;
  }, {onError});
  return enabled ? run() : confirm({
   title: 'End the advanced preview?',
   body: 'Keep one active room with four places. Other rooms, tasks and reports remain read only; repeating activities pause.',
   action: 'End preview', run
  });
 }
