function RoomSettings({readOnly=false,maximum=4,room,memberCount,removed,busy,onSave,onRound,onRestore,confirm}){
 const from=()=>({name:room.name,capacity:room.capacity,goalMinutes:room.goalMinutes,invitationsOpen:room.invitationsOpen,version:room.version});const [draft,setDraft]=useState(from),[copy,setCopy]=useState('');
 const patch=values=>setDraft(d=>({...d,...values}));
 async function save(e){e.preventDefault();const result=await onSave(draft);if(result)patch({version:result.version});}
 if(readOnly&&!room.closed)return <div><p>This room is read only. Its records are kept. You can choose it as your free room above, restore a subscription, or close it.</p><button className="button danger" disabled={busy} onClick={()=>confirm({title:'Close this read-only room?',body:'Retained records are kept. Closing the room releases an ownership place and cannot be undone.',action:'Close room',run:()=>onSave({...from(),close:true,invitationsOpen:false})})}>Close room</button></div>;
 return <details className="community-owner" open><summary>Manage room</summary><form onSubmit={save} className="community-form"><label className="field">Room name<input value={draft.name} onChange={e=>patch({name:e.target.value})} maxLength="60" required/></label><div className="room-goal-field"><label className="field">{sharedGoalLabel}<input aria-describedby="settings-room-goal-help" type="number" min="1" max="11520" value={draft.goalMinutes} onChange={e=>patch({goalMinutes:Number(e.target.value)})} required/></label><p id="settings-room-goal-help" className="help">{sharedGoalHelp}</p></div><RoomCapacity maximum={maximum} value={draft.capacity} onChange={capacity=>patch({capacity:Number(capacity)})} minimum={Math.max(2,memberCount)} disabled={busy||room.closed}/><label className="switch-row"><span>Allow invitations and new joins</span><input type="checkbox" checked={draft.invitationsOpen} onChange={e=>patch({invitationsOpen:e.target.checked})}/></label>{room.version!==draft.version&&<p className="help">Settings changed elsewhere. <button className="text-button" type="button" onClick={()=>setDraft(from())}>Use latest settings</button></p>}<button className="button primary" disabled={busy||room.closed}>Save room settings</button></form>
 {!room.closed&&<><label className="field">Invitation code<input readOnly value={room.inviteCode||''}/></label><div className="community-row"><button className="button" disabled={busy||!room.invitationsOpen} onClick={async()=>{try{await navigator.clipboard.writeText(location.origin+'/study-groups?invite='+room.inviteCode);setCopy('Invitation copied. Share it only with intended members.');}catch{setCopy('Clipboard unavailable. Copy the invitation code above.');}}}>Copy invitation link</button><button className="button" disabled={busy} onClick={async()=>{const result=await onSave({...draft,rotateInvite:true});if(result)patch({version:result.version});}}>Replace invitation code</button></div>{copy&&<p className="help" role="status">{copy}</p>}<h3>Optional shared focus round</h3><p className="help">Members can choose the same finish time. Each member starts and pauses their own timer; no shared time is added automatically. Clearing the round does not pause existing personal timers.</p><div className="community-row"><button className="button" disabled={busy} onClick={()=>onRound(25)}>Set a 25-minute round</button><button className="button" disabled={busy} onClick={()=>onRound(0)}>Clear shared round</button></div><button className="button danger" disabled={busy} onClick={()=>confirm({title:'Close this room?',body:'This stops room timers, closes invitations and hides the room from the public directory. You can still review its retained data. This room cannot be reopened.',action:'Close room',run:async()=>!!await onSave({...draft,close:true,invitationsOpen:false})})}>Close room</button></>}
 {removed.length>0&&<details><summary>Removed members</summary>{removed.map(m=><div className="community-row" key={m.id}><span>{m.nickname}</span><button className="button" disabled={busy||room.closed} onClick={()=>onRestore(m.id)}>Restore access</button></div>)}</details>}</details>;
}
function Moderation({reports,busy,onReview,confirm}){return reports.length?<div>{reports.map(r=><article className="community-report" key={r.id}><strong>{r.room_name} · {r.reason}</strong><p className="help">Message by {r.author||'a former member'}</p><p>{r.excerpt}</p>{r.detail&&<p>{r.detail}</p>}<div className="community-row">{[['hide','Hide message'],['mute','Mute 24h'],['remove','Remove member'],['dismiss','Dismiss report']].map(([action,label])=><button key={action} className="button" disabled={busy} onClick={()=>action==='remove'?confirm({title:r.subject_id===r.owner_id?'Close this owner’s room?':'Remove this member?',body:r.subject_id===r.owner_id?'Removing the owner also closes this room and stops all its timers. It cannot be reopened.':'This revokes room access and stops the member’s room timer.',action:r.subject_id===r.owner_id?'Close room':'Remove member',run:()=>onReview(r.id,action)}):onReview(r.id,action)}>{label}</button>)}</div></article>)}</div>:<p className="help">No open reports for you to review.</p>;}

export {Leaderboard} from './Leaderboard.jsx';
